#!/usr/bin/env bash
set -euo pipefail
[[ $# == 1 && ( $1 == original-cpu || $1 == static ) ]]||{ echo "usage: $0 original-cpu|static" >&2;exit 2; }
MODE=$1;ROOT=$(git rev-parse --show-toplevel);EXP="$ROOT/experiments/0014-pocket-fp-onnx-qnn-htp";E12="$ROOT/experiments/0012-pocket-onnx-vs-executorch-android";ORT="$ROOT/experiments/0010-supertonic-qnn-htp-feasibility/.local/ort-v1.27.1-qnn-2.49.0-android-arm64/Release";INC="$ROOT/experiments/0010-supertonic-qnn-htp-feasibility/.local/onnxruntime-v1.27.1-source/include/onnxruntime/core/session";NDK=${ANDROID_NDK_ROOT:-/home/moritz/opt/android-sdk/ndk/26.2.11394342};QAIRT=${QAIRT_SDK_ROOT:-/home/moritz/opt/qairt/2.49.0.260730};CC="$NDK/toolchains/llvm/prebuilt/linux-x86_64/bin/aarch64-linux-android27-clang++"
if [[ $MODE == original-cpu ]];then STAGE="$EXP/.local/alba-cpu-stage";SOURCE=pocket_alba_cpu_runner.cc;BIN=pocket_alba_cpu_runner;else STAGE="$EXP/.local/alba-static-stage";SOURCE=pocket_alba_static_runner.cc;BIN=pocket_alba_static_runner;fi
rm -rf "$STAGE";mkdir -p "$STAGE/model" "$STAGE/lib" "$STAGE/assets";"$CC" -std=c++17 -O2 -fPIE -pie -I"$INC" "$EXP/tools/$SOURCE" -L"$ORT" -lonnxruntime -Wl,-rpath,'$ORIGIN/lib' -o "$STAGE/$BIN";cp "$ORT/libonnxruntime.so" "$STAGE/lib/";cp "$NDK/toolchains/llvm/prebuilt/linux-x86_64/sysroot/usr/lib/aarch64-linux-android/libc++_shared.so" "$STAGE/lib/";cp "$EXP/work/quality-recovery/alba-assets/alba-flow-cache-v1.f32" "$STAGE/assets/";cp "$EXP/work/quality-recovery/alba-assets/numpy-randomstate-seed0-temp0p3-134x32.f32" "$STAGE/assets/"
if [[ $MODE == original-cpu ]];then B="$E12/.local/onnx-controlled";cp "$B/"{text_conditioner.onnx,flow_lm_main.onnx,flow_lm_flow.onnx,mimi_decoder.onnx} "$STAGE/model/";MANIFEST="$EXP/work/quality-recovery/alba-android-cpu-stage.sha256";else cp "$EXP/.local/static-optimized/text_conditioner-text26.onnx" "$STAGE/model/text_conditioner.onnx";cp "$EXP/.local/qnn-flow/flow_lm_prefill_text26.onnx" "$STAGE/model/flow_prefill_text26.onnx";cp "$EXP/.local/qnn-flow/flow_lm_ar_bos1.onnx" "$STAGE/model/flow_ar_bos1.onnx";cp "$EXP/.local/qnn-flow/flow_lm_ar_latent1.onnx" "$STAGE/model/flow_ar_latent1.onnx";cp "$EXP/.local/static-optimized/flow_lm_flow-flow1.onnx" "$STAGE/model/flow.onnx";for n in 12 6 1;do cp "$EXP/.local/qnn-v2/mimi_decoder-decoder$n.onnx" "$STAGE/model/mimi_decoder$n.onnx";done;cp "$QAIRT/lib/aarch64-android/"{libQnnHtp.so,libQnnHtpPrepare.so,libQnnHtpV73Stub.so,libQnnSystem.so} "$STAGE/lib/";cp "$QAIRT/lib/hexagon-v73/unsigned/libQnnHtpV73Skel.so" "$STAGE/lib/";MANIFEST="$EXP/work/quality-recovery/alba-static-android-stage.sha256";fi
(cd "$STAGE"&&find . -type f -exec sha256sum {} +|sort)>"$MANIFEST";du -sh "$STAGE";echo "$MANIFEST"
